constraint.cypher:
MATCH (m:Module)
    WHERE NOT EXISTS { MATCH (:Type:Test)-[:DEPENDS_ON]->(x:Type) WHERE x.fqn STARTS WITH m.fqn + '.' }
    RETURN m AS Element, m.fqn AS Fqn, 'no test depends on this module' AS Detail

MATCH (t:Type)-[:DECLARES]->(m:Method:MessageConsumer)
    WHERE NOT t:Test AND NOT EXISTS { MATCH (:Type:Test)-[:DEPENDS_ON]->(t) }
    RETURN DISTINCT m AS Element, t.fqn AS Fqn, m.signature AS Detail

MATCH (t:Type)-[:DECLARES]->(m:Method:Endpoint)
    WHERE NOT t:Test AND NOT EXISTS { MATCH (:Type:Test)-[:DEPENDS_ON]->(t) }
    RETURN DISTINCT m AS Element, t.fqn AS Fqn, m.httpMethod + ' ' + coalesce(m.fullPath, '') AS Detail
